import { Component, EventEmitter, Input } from '@angular/core';

@Component({
  selector: 'app-latder',
  templateUrl: './latder.component.html',
  styleUrls: ['./latder.component.css']
})
export class LatderComponent {
  public idUsuario : any = null

  recogerId(idUsuario : any){
    this.idUsuario=idUsuario;
    console.log("Nuevo id latder:"+idUsuario);
  }

}
<app-login (enviarId)="recogerId($event)"></app-login>
<i class="bi bi-shopping-cart" style="font-size: 24px; margin: 0 10px;"></i>
<app-carrito (enviarId)="recogerId($event)" [idUsuario]="idUsuario"></app-carrito>
